import{_ as t,c as a,o as r,aj as i}from"./chunks/framework.CDhdelVI.js";const u=JSON.parse(`{"title":"Convert Recipes with the Calculator","description":"Turn a written recipe into baker's percentages, then scale it up or down in the KitchenRatio calculator.","frontmatter":{"title":"Convert Recipes with the Calculator","description":"Turn a written recipe into baker's percentages, then scale it up or down in the KitchenRatio calculator.","head":[["meta",{"name":"description","content":"Turn a written recipe into baker's percentages, then scale it up or down in the KitchenRatio calculator."}],["meta",{"property":"og:title","content":"Convert Recipes with the Calculator"}],["meta",{"property":"og:description","content":"Turn a written recipe into baker's percentages, then scale it up or down in the KitchenRatio calculator."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/guides/calculator-for-recipes.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Convert Recipes with the Calculator"}],["meta",{"name":"twitter:description","content":"Turn a written recipe into baker's percentages, then scale it up or down in the KitchenRatio calculator."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/guides/calculator-for-recipes.html"}]]},"headers":[],"relativePath":"guides/calculator-for-recipes.md","filePath":"guides/calculator-for-recipes.md"}`),l={name:"guides/calculator-for-recipes.md"};function n(o,e,c,s,h,p){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="convert-recipes-with-the-calculator" tabindex="-1">Convert Recipes with the Calculator <a class="header-anchor" href="#convert-recipes-with-the-calculator" aria-label="Permalink to “Convert Recipes with the Calculator”">​</a></h1><p>Turn any written recipe into baker&#39;s percentages, then scale it like a pro. Think of this as reverse&#39;engineering a dough: grams in, ratios out, repeatable forever.</p><h2 id="step-1-set-the-flour-baseline" tabindex="-1">Step 1: Set the Flour Baseline <a class="header-anchor" href="#step-1-set-the-flour-baseline" aria-label="Permalink to “Step 1: Set the Flour Baseline”">​</a></h2><p>Put your recipe&#39;s flour weight into the Flour card. That number is your 100%.</p><h2 id="step-2-match-ingredients-by-grams" tabindex="-1">Step 2: Match Ingredients by Grams <a class="header-anchor" href="#step-2-match-ingredients-by-grams" aria-label="Permalink to “Step 2: Match Ingredients by Grams”">​</a></h2><p>Add the ingredients you need (water, salt, yeast, enrichments).<br> Move each slider until the grams shown match your recipe&#39;s weight.<br> The calculator reveals the percentage as you dial it in.</p><h2 id="step-3-capture-the-ratio" tabindex="-1">Step 3: Capture the Ratio <a class="header-anchor" href="#step-3-capture-the-ratio" aria-label="Permalink to “Step 3: Capture the Ratio”">​</a></h2><p>Once the grams match, the percentages are the recipe.<br> Write them down. They are now portable and scalable.</p><h2 id="step-4-scale-the-batch" tabindex="-1">Step 4: Scale the Batch <a class="header-anchor" href="#step-4-scale-the-batch" aria-label="Permalink to “Step 4: Scale the Batch”">​</a></h2><p>Keep the percentages fixed and change the flour weight.<br> Every ingredient updates automatically.</p><h2 id="example-workflow" tabindex="-1">Example Workflow <a class="header-anchor" href="#example-workflow" aria-label="Permalink to “Example Workflow”">​</a></h2><ol><li>Flour is 500g - set Flour to 500g.</li><li>Water is 325g - slide water to 325g (65%).</li><li>Salt 10g - slide salt to 10g (2%).</li><li>Yeast 2.5g - slide yeast to 2.5g (0.5%).</li><li>Increase flour to 800g to scale the entire recipe.</li></ol><h2 id="practical-tips" tabindex="-1">Practical Tips <a class="header-anchor" href="#practical-tips" aria-label="Permalink to “Practical Tips”">​</a></h2><ul><li>Weigh everything in grams. Volumes lie.</li><li>If your recipe has oil, sugar, eggs, or dairy, add them with Add Ingredient.</li><li>Use presets as a starting point, then dial in the exact grams.</li></ul><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><ul><li><a href="/guides/kitchenratio-calculator.html">KitchenRatio Calculator</a></li><li><a href="/guides/bakers-percentage.html">Baker&#39;s Percentage</a></li><li><a href="/guides/hydration.html">Hydration</a></li></ul>',16)])])}const g=t(l,[["render",n]]);export{u as __pageData,g as default};
